<script setup lang="ts">
import {ref,onMounted,computed,watch} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>()
const rows=ref<Row[]>([]),users=ref<Row[]>([]),nodes=ref<Row[]>([]),clients=ref<Row[]>([]),editing=ref<Row|null>(null),busy=ref(false),error=ref(''),notice=ref(''),groups=ref<Row[]>([]),rules=ref<string[]>([]),rule=ref({type:'DOMAIN-SUFFIX',value:'netflix.com',target:'📺 流媒体'}),native=ref('{}')
const visualDirty=ref(false),sourceDirty=ref(false);let hydrating=false
watch([groups,rules],()=>{if(!hydrating&&editing.value)visualDirty.value=true},{deep:true,flush:'sync'})
watch(()=>editing.value?.source,()=>{if(!hydrating&&editing.value)sourceDirty.value=true},{flush:'sync'})
const targets=computed(()=>['DIRECT','REJECT','PROXY',...groups.value.map(g=>g.name),...nodes.value.filter(n=>!n.delete_requested_at).map(n=>'node:'+n.id),...Array.from(new Set(nodes.value.map(n=>'protocol:'+n.kind)))])
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function load(){[rows.value,users.value,nodes.value,clients.value]=await Promise.all(['client-policies','proxy-users','live','client-catalog'].map(p=>props.api(p)))}
onMounted(()=>void run(load))
function create(){editing.value={name:'默认分流',user_id:'',client_id:'all',version:0,source:''};groups.value=[{name:'🚀 节点选择',type:'select',proxies:['ALL']},{name:'♻️ IPv4自动',type:'url-test',proxies:['family:ipv4'],url:'https://www.gstatic.com/generate_204',interval:300},{name:'📺 流媒体',type:'select',proxies:['🚀 节点选择','♻️ IPv4自动','DIRECT']}];rules.value=['DOMAIN-SUFFIX,netflix.com,📺 流媒体','DOMAIN-SUFFIX,netflix.net,📺 流媒体','DOMAIN-SUFFIX,nflxvideo.net,📺 流媒体','MATCH,🚀 节点选择'];native.value='{}';void run(serialize)}
async function serialize(){if(!editing.value)return;const r=await props.api('client-policies/parse','POST',{policy:{'proxy-groups':groups.value,rules:rules.value}});hydrating=true;editing.value.source=r.source;hydrating=false;visualDirty.value=false;sourceDirty.value=false}
async function parse(){if(!editing.value)return;const r=await props.api('client-policies/parse','POST',{source:editing.value.source});hydrating=true;groups.value=r.policy['proxy-groups']??[];rules.value=r.policy.rules??[];hydrating=false;visualDirty.value=false;sourceDirty.value=false}
function edit(row:Row){editing.value=JSON.parse(JSON.stringify(row));native.value=JSON.stringify(row.native_options??{},null,2);void run(parse)}
function save(){void run(async()=>{if(visualDirty.value&&sourceDirty.value)throw new Error('可视化与 YAML 均已修改，请先选择“表单 → YAML”或“YAML → 表单”保留需要的版本');if(visualDirty.value)await serialize();const v=editing.value!;await props.api('client-policies'+(v.id?'/'+v.id:''),v.id?'PUT':'POST',{name:v.name,user_id:v.user_id??'',client_id:v.client_id,source:v.source,native_options:JSON.parse(native.value),version:v.version});editing.value=null;notice.value='已保存，下一次更新订阅自动生效';await load()})}
function remove(row:Row){if(!window.confirm('删除策略 '+row.name+'？订阅将回退到下一层策略或默认配置。'))return;void run(async()=>{await props.api('client-policies/'+row.id,'DELETE');await load()})}
function nodeName(id:string){const n=nodes.value.find(n=>'node:'+n.id===id);return n?`${n.name} · ${n.kind}${n.online?'':' · 待上线'}`:id}
function addRule(){if(!rule.value.target)return;const line=rule.value.type==='MATCH'?'MATCH,'+rule.value.target:[rule.value.type,rule.value.value,rule.value.target].join(',');const last=rules.value.at(-1)?.startsWith('MATCH,');if(rule.value.type==='MATCH'){rules.value=rules.value.filter(r=>!r.startsWith('MATCH,'));rules.value.push(line)}else rules.value.splice(last?rules.value.length-1:rules.value.length,0,line)}
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><h2>客户端策略组与规则</h2><p class="muted">用户专用优先于全局；同一用户下客户端专用优先于通用。只发布该用户获授权且已运行的节点。</p></div><button class="primary" @click="create">＋ 添加策略</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><div class="table-scroll"><table><thead><tr><th>策略</th><th>用户范围</th><th>客户端</th><th>版本 / 操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.name}}</td><td>{{users.find(u=>u.id===r.user_id)?.name??'所有用户 / 共享订阅'}}</td><td>{{clients.find(c=>c.id===r.client_id)?.name??'全部客户端'}}</td><td>v{{r.version}} <button class="text-button" @click="edit(r)">编辑</button><button class="text-button danger" @click="remove(r)">删除</button></td></tr></tbody></table></div><p v-if="!rows.length" class="console-empty">添加分流策略后，分享的完整配置会自动带入策略组与规则。</p><p class="form-note">Mihomo 保留原生选择与自动测速。sing-box 转为 selector / urltest；Xray 手动组固定选第一个成员，测速组转换为 balancer。无法等价转换的规则会给出错误，请为该客户端设置专用策略。URI 节点列表不携带规则。</p></section>
<div v-if="editing" class="modal-backdrop"><form class="modal topology-editor" role="dialog" aria-modal="true" aria-label="客户端分流策略" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'编辑':'添加'}}客户端策略</h2><button class="secondary" type="button" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" class="error" role="alert">{{error}}</p><div class="fields"><label>名称<input v-model="editing.name" required maxlength="100"></label><label>所属用户<select v-model="editing.user_id"><option value="">所有用户 / 共享订阅</option><option v-for="u in users" :value="u.id" :key="u.id">{{u.name}}</option></select></label><label>客户端<select v-model="editing.client_id"><option value="all">通用（自动转换）</option><option v-for="c in clients.filter(c=>c.full_config)" :value="c.id" :key="c.id">{{c.name}}</option></select></label></div>
<h3>可视化策略组</h3><p class="muted">ALL、协议及 IP 类型是动态匹配；新增的获授权节点会自动进入。指定节点使用稳定 ID，重命名不会失效。</p><section v-for="(g,i) in groups" :key="i" class="panel"><div class="fields"><label>组名<input v-model="g.name" required></label><label>类型<select v-model="g.type"><option>select</option><option>url-test</option><option>fallback</option><option>load-balance</option></select></label><label v-if="g.type!=='select'">测速间隔（秒）<input v-model.number="g.interval" type="number" min="1" max="86400"></label></div><div class="choice-list"><label v-for="r in ['ALL','family:ipv4','family:ipv6','DIRECT','REJECT',...Array.from(new Set(nodes.map(n=>'protocol:'+n.kind))),...nodes.filter(n=>!n.delete_requested_at).map(n=>'node:'+n.id),...groups.filter(x=>x!==g).map(x=>x.name)]" :key="r"><input type="checkbox" v-model="g.proxies" :value="r">{{nodeName(r)}}</label></div><p class="muted">当前顺序：{{g.proxies.map(nodeName).join(' → ')}}；可在 YAML 中调整优先级。</p><button type="button" class="text-button danger" @click="groups.splice(i,1)">删除此组</button></section><button type="button" class="secondary" @click="groups.push({name:'策略组'+(groups.length+1),type:'select',proxies:['ALL']})">添加策略组</button>
<h3>规则编写</h3><div class="fields"><label>规则类型<select v-model="rule.type"><option v-for="t in ['DOMAIN','DOMAIN-SUFFIX','DOMAIN-KEYWORD','IP-CIDR','IP-CIDR6','SRC-IP-CIDR','DST-PORT','SRC-PORT','NETWORK','PROCESS-NAME','PROCESS-PATH','GEOIP','GEOSITE','MATCH']" :key="t">{{t}}</option></select></label><label v-if="rule.type!=='MATCH'">匹配内容<input v-model="rule.value"></label><label>目标组 / 节点 / 协议<select v-model="rule.target"><option v-for="t in targets" :key="t" :value="t">{{nodeName(t)}}</option></select></label></div><button type="button" class="secondary" @click="addRule">加入规则</button><div v-for="(r,i) in rules" :key="i" class="section-heading"><code>{{r}}</code><span><button type="button" class="text-button" :disabled="i===0" @click="[rules[i-1],rules[i]]=[rules[i],rules[i-1]]">↑</button><button type="button" class="text-button danger" @click="rules.splice(i,1)">删除</button></span></div>
<div class="row-actions"><button type="button" class="secondary" :disabled="busy" @click="run(serialize)">表单 → YAML</button><button type="button" class="secondary" :disabled="busy" @click="run(parse)">YAML → 表单</button></div><label>Mihomo 策略源（保存此内容）<textarea v-model="editing.source" rows="18" class="native-preview" maxlength="32768" spellcheck="false"></textarea></label><p class="form-note">可视化修改会在保存时自动写入 YAML；同时修改两处时必须先选择同步方向，避免丢失修改。无可用节点的目标会拒绝连接，不会自动改成直连。</p><details><summary>按内核手动覆盖客户端设置</summary><p class="muted">JSON 对象，键为 mihomo、sing-box 或 xray，值可填写对应 DNS、路由及本地入站设置；身份凭据与已授权节点由系统生成。订阅关联模板的覆盖最后生效。</p><textarea v-model="native" rows="12" class="native-preview" spellcheck="false" placeholder='{"mihomo":{"dns":{"enable":true}}}'></textarea></details></div><div class="modal-footer"><button type="button" class="secondary" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存策略</button></div></form></div></template>
<style scoped>.topology-editor{width:min(1100px,96vw)}code{overflow-wrap:anywhere;font-size:12px}.panel .panel{padding:16px;margin:12px 0}.row-actions{margin:18px 0}</style>
